import { jsPDF } from "jspdf"

export function import_EncodeSansCond_Regular() {
  var font = "";
  var callAddFont = function () {
    this.addFileToVFS( "EncodeSansCondensed-Regular-normal.ttf", font );
    this.addFont( "EncodeSansCondensed-Regular-normal.ttf",
      "EncodeSansCondensed-Regular",
      "italic" );
  };
  jsPDF.API.events.push( [ "addFonts", callAddFont ] )
}
